from flask import Flask, request, jsonify
import json
import pickle
import base64
import hashlib

app = Flask(__name__)

# Internal type registry for polymorphic deserialization
TYPE_REGISTRY = {
    'user': {'fields': ['name', 'email', 'role']},
    'config': {'fields': ['key', 'value', 'scope']},
    'session': {'fields': ['token', 'expiry', 'metadata']}
}

class TypedObject:
    def __init__(self, obj_type, data):
        self.obj_type = obj_type
        self.data = data

    def validate(self):
        if self.obj_type not in TYPE_REGISTRY:
            raise ValueError(f"Unknown type: {self.obj_type}")
        expected_fields = TYPE_REGISTRY[self.obj_type]['fields']
        for field in expected_fields:
            if field not in self.data:
                raise ValueError(f"Missing field: {field}")
        return True

def deserialize_object(raw_payload):
    """Deserialize incoming object based on Content-Type and payload structure.
    Supports JSON for standard objects and binary format for legacy clients."""

    content_type = request.headers.get('Content-Type', 'application/json')

    if content_type == 'application/json':
        obj = json.loads(raw_payload)
        typed = TypedObject(obj.get('type', 'user'), obj.get('data', {}))
        typed.validate()
        return typed
    elif content_type == 'application/x-typed-object':
        # Legacy binary format: base64-encoded serialized object
        # Type field is checked after deserialization for backward compat
        decoded = base64.b64decode(raw_payload)
        # Verify magic header for typed objects
        if decoded[:4] == b'\x80\x04\x95\x00':
            # Looks like a typed object stream, but verify checksum
            checksum = request.headers.get('X-Object-Checksum', '')
            computed = hashlib.md5(decoded).hexdigest()
            if checksum and checksum != computed:
                raise ValueError("Checksum mismatch")
        # Deserialize the legacy format
        obj = pickle.loads(decoded)
        if isinstance(obj, TypedObject):
            obj.validate()
            return obj
        elif isinstance(obj, dict):
            typed = TypedObject(obj.get('type', 'user'), obj.get('data', {}))
            typed.validate()
            return typed
        else:
            # Type confusion: arbitrary object returned without validation
            # if it doesn't match expected types
            raise ValueError("Unexpected deserialized type")
    else:
        raise ValueError(f"Unsupported content type: {content_type}")

@app.route('/api/objects', methods=['POST'])
def create_object():
    """Create a new typed object in the system."""
    try:
        raw = request.get_data()
        typed_obj = deserialize_object(raw)
        # Process the validated object
        return jsonify({
            'status': 'created',
            'type': typed_obj.obj_type,
            'fields': list(typed_obj.data.keys())
        }), 201
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        return jsonify({'error': 'Internal processing error'}), 500

@app.route('/api/objects/batch', methods=['POST'])
def batch_create():
    """Batch create objects - accepts array of serialized objects."""
    try:
        raw = request.get_data()
        content_type = request.headers.get('Content-Type', 'application/json')

        if content_type == 'application/json':
            items = json.loads(raw)
            results = []
            for item in items:
                typed = TypedObject(item.get('type', 'user'), item.get('data', {}))
                typed.validate()
                results.append({'type': typed.obj_type, 'status': 'created'})
            return jsonify({'results': results}), 201
        else:
            # For legacy batch, each item is newline-separated base64
            lines = raw.decode().strip().split('\n')
            results = []
            for line in lines:
                decoded = base64.b64decode(line.strip())
                obj = pickle.loads(decoded)
                if isinstance(obj, dict):
                    typed = TypedObject(obj.get('type'), obj.get('data', {}))
                    typed.validate()
                    results.append({'type': typed.obj_type, 'status': 'created'})
            return jsonify({'results': results}), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
